package ai

import (
	"context"
	"errors"
	"strings"
	"time"

	"gorm.io/gorm"
	"gorm.io/gorm/clause"

	"github.com/kaptree/kapoj/apps/server/internal/httpx"
)

// HintInput is the request body for POST /api/ai/hint.
type HintInput struct {
	ProblemID int64 `json:"problemId"`
}

// HintView is the cached problem hint returned to clients. Cached reports
// whether the content came from an existing ai_hints row rather than being
// freshly generated by this request.
type HintView struct {
	Hint   string `json:"hint"`
	Cached bool   `json:"cached"`
}

// hintContext is the minimal problem row used to build the hint prompt.
type hintContext struct {
	Title          string
	StatementMD    string
	InputFormatMD  string
	OutputFormatMD string
	HintMD         string
	IsPublic       bool
}

// Hint returns the AI hint for a problem, generating and caching it on the
// first request. The cache is consulted before any config/limiter/client work,
// so users can read an existing hint without their own AI key.
func (s *Service) Hint(ctx context.Context, userID, problemID int64, canViewHidden bool) (HintView, error) {
	var p hintContext
	err := s.db.WithContext(ctx).
		Table("problems").
		Select("title", "statement_md", "input_format_md", "output_format_md", "hint_md", "is_public").
		Where("id = ?", problemID).
		First(&p).Error
	if errors.Is(err, gorm.ErrRecordNotFound) {
		return HintView{}, httpx.ErrNotFound
	}
	if err != nil {
		return HintView{}, err
	}
	if !p.IsPublic && !canViewHidden {
		// Do not reveal the existence of hidden problems.
		return HintView{}, httpx.ErrNotFound
	}

	// Cache hit: return immediately without requiring config or a limiter.
	var hint Hint
	err = s.db.WithContext(ctx).Where("problem_id = ?", problemID).First(&hint).Error
	if err == nil {
		return HintView{Hint: hint.Content, Cached: true}, nil
	}
	if !errors.Is(err, gorm.ErrRecordNotFound) {
		return HintView{}, err
	}

	// Cache miss: require the user's AI config, apply the rate limit, and call
	// the model.
	req, err := s.chatRequest(ctx, userID)
	if err != nil {
		return HintView{}, err
	}
	if err := s.checkLimit(ctx, userID); err != nil {
		return HintView{}, err
	}
	req.Messages = hintMessages(p)
	req.Temperature = generationTemperature
	out, err := s.client.Chat(ctx, req)
	if err != nil {
		return HintView{}, httpx.ErrBadGateway
	}
	content := strings.TrimSpace(out)
	if content == "" {
		content = "暂无可用的 AI 提示。"
	}

	inserted := Hint{
		ProblemID: problemID,
		Content:   content,
		CreatedBy: userID,
		CreatedAt: time.Now(),
	}
	res := s.db.WithContext(ctx).
		Clauses(clause.OnConflict{Columns: []clause.Column{{Name: "problem_id"}}, DoNothing: true}).
		Create(&inserted)
	if res.Error != nil {
		return HintView{}, res.Error
	}

	// Read the final row: ours when RowsAffected == 1, otherwise a concurrent
	// writer's content. RowsAffected == 0 means someone else inserted first.
	var final Hint
	if err := s.db.WithContext(ctx).Where("problem_id = ?", problemID).First(&final).Error; err != nil {
		return HintView{}, err
	}
	return HintView{Hint: final.Content, Cached: res.RowsAffected == 0}, nil
}

// hintMessages asks the model for a Chinese hint without a full solution.
func hintMessages(p hintContext) []ChatMessage {
	system := "你是一名编程竞赛辅导助手。请针对给定题目给出解题提示，只返回中文提示，不要输出完整题解、解题代码或 Markdown 代码块。"
	var b strings.Builder
	b.WriteString("题目：")
	b.WriteString(p.Title)
	if p.StatementMD != "" {
		b.WriteString("\n\n题目描述：\n")
		b.WriteString(p.StatementMD)
	}
	if p.InputFormatMD != "" {
		b.WriteString("\n\n输入格式：\n")
		b.WriteString(p.InputFormatMD)
	}
	if p.OutputFormatMD != "" {
		b.WriteString("\n\n输出格式：\n")
		b.WriteString(p.OutputFormatMD)
	}
	if p.HintMD != "" {
		b.WriteString("\n\n题目原有提示：\n")
		b.WriteString(p.HintMD)
	}
	b.WriteString("\n\n请给出解题提示。")
	return []ChatMessage{
		{Role: "system", Content: system},
		{Role: "user", Content: b.String()},
	}
}
